const formData = $('Form: Write Announcement').first().json;
const usersRaw = $input.first().json;
const users = Array.isArray(usersRaw) ? usersRaw : [];

const subject = formData['Email Subject'] || 'Announcement from NIRVANA MART';
const title = formData['Announcement Title'] || 'Important Update';
const body = formData['Message Body'] || '';
const btnText = formData['Button Text'] || 'Visit NIRVANA MART';
const btnUrl = formData['Button URL'] || 'https://nirvana-mart.onrender.com';

const emailsToSend = users
  .filter(u => u.email)
  .map(u => ({
    to: u.email,
    name: u.name || 'Student',
    subject,
    html: `
<div style="font-family:'Segoe UI',sans-serif;max-width:600px;margin:0 auto;background:#f5f5f5;padding:24px;border-radius:12px;">
  <div style="background:linear-gradient(135deg,#0a0a14,#1a102a);padding:32px;border-radius:10px;text-align:center;margin-bottom:24px;">
    <img src="https://nirvana-mart.onrender.com/LOGO.png" style="height:50px;margin-bottom:16px;" alt="NIRVANA MART">
    <h1 style="color:#e8b86d;margin:0;font-size:1.4rem;">${title}</h1>
  </div>
  <div style="background:white;padding:24px;border-radius:10px;margin-bottom:20px;">
    <p style="color:#555;line-height:1.7;font-size:0.95rem;">Hi <strong>${u.name || 'there'}</strong>,</p>
    <div style="color:#333;line-height:1.8;font-size:0.95rem;">${body.replace(/\n/g, '<br>')}</div>
  </div>
  ${btnUrl ? `<div style="text-align:center;margin-bottom:20px;"><a href="${btnUrl}" style="display:inline-block;background:#c8923a;color:white;padding:14px 32px;border-radius:8px;text-decoration:none;font-weight:700;font-size:1rem;">${btnText} →</a></div>` : ''}
  <p style="color:#aaa;font-size:0.78rem;text-align:center;">You received this because you're a NIRVANA MART member. <a href="${btnUrl || 'https://nirvana-mart.onrender.com'}" style="color:#c8923a;">Visit Platform</a></p>
</div>`
  }));

return emailsToSend.map(e => ({ json: e }));
